<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {api} from '@/api';import {useAuthStore} from '@/stores/auth';import {ElMessage} from 'element-plus';import {Plus,Lock,Document,Calendar} from '@element-plus/icons-vue';
const auth=useAuthStore(),tasks=ref<any[]>([]),vulns=ref<any[]>([]),dialog=ref(false),active=ref('vulns');const form=ref({title:'',type:'PENETRATION',description:'',targetAssets:'',startDate:'',endDate:'',rewardAmount:0,difficulty:'INTERMEDIATE',minSeverity:'MEDIUM',memberLimit:10});const canManage=computed(()=>['COMPANY','ADMIN'].includes(auth.user?.role||'')),canCreate=computed(()=>auth.user?.role==='COMPANY');async function load(){if(!auth.loggedIn)return;try{[tasks.value,vulns.value]=await Promise.all([api.get('/task/mine'),api.get('/vulnerability/list')])}catch(e:any){ElMessage.error(e.message)}}onMounted(load);async function create(){try{await api.post('/task/create',form.value);ElMessage.success('任务已创建');dialog.value=false;load()}catch(e:any){ElMessage.error(e.message)}}async function review(id:number,status:string,severity:string){try{await api.put(`/vulnerability/${id}/review`,{status,severity,reviewComment:status==='CONFIRMED'?'企业已复现并确认':'暂未通过复现'});ElMessage.success('审核结果已提交');load()}catch(e:any){ElMessage.error(e.message)}}
</script>
<template><div class="page"><div class="page-head"><div><span class="eyebrow">Enterprise security operations</span><h1>企业安全工作台</h1><p>统一管理授权任务、白帽协作日报与漏洞审核。</p></div><el-button v-if="canCreate" type="primary" :icon="Plus" @click="dialog=true">创建安全任务</el-button></div><div v-if="!canManage" class="panel role-notice"><Lock/><div><h3>当前为白帽研究员视角</h3><p>你可以查看自己提交的漏洞记录；任务创建和漏洞审核仅对企业与平台管理员开放。</p></div></div><section class="ops-stats"><div class="panel"><Lock/><span><small>管理任务</small><b>{{tasks.length}}</b></span></div><div class="panel"><Document/><span><small>漏洞报告</small><b>{{vulns.length}}</b></span></div><div class="panel"><Calendar/><span><small>待审核</small><b>{{vulns.filter(v=>v.status==='SUBMITTED').length}}</b></span></div></section><div class="ops-tabs"><button :class="{active:active==='vulns'}" @click="active='vulns'">漏洞管理</button><button :class="{active:active==='tasks'}" @click="active='tasks'">任务管理</button></div><div class="panel table-wrap" v-if="active==='vulns'"><el-table :data="vulns"><el-table-column prop="reportNo" label="报告编号" width="160"/><el-table-column prop="title" label="漏洞标题" min-width="220"/><el-table-column prop="vulnerabilityType" label="类型" width="130"/><el-table-column label="风险" width="90"><template #default="s"><b :class="'severity-'+s.row.severity.toLowerCase()">{{s.row.severity}}</b></template></el-table-column><el-table-column prop="cvssScore" label="CVSS" width="75"/><el-table-column prop="status" label="状态" width="120"/><el-table-column v-if="canManage" label="审核操作" width="170"><template #default="s"><template v-if="s.row.status==='SUBMITTED'||s.row.status==='NEED_MORE_INFO'"><el-button link type="success" @click="review(s.row.id,'CONFIRMED',s.row.severity)">确认</el-button><el-button link type="danger" @click="review(s.row.id,'REJECTED',s.row.severity)">驳回</el-button></template><span v-else>已终审</span></template></el-table-column></el-table><div v-if="!vulns.length" class="empty">暂无漏洞报告</div></div><div class="panel table-wrap" v-else><el-table :data="tasks"><el-table-column prop="taskNo" label="任务编号" width="160"/><el-table-column prop="title" label="任务名称" min-width="240"/><el-table-column prop="type" label="类型" width="130"/><el-table-column prop="rewardAmount" label="赏金" width="120"/><el-table-column prop="endDate" label="截止日期" width="120"/><el-table-column prop="status" label="状态" width="100"/></el-table><div v-if="!tasks.length" class="empty">暂无任务记录</div></div><el-dialog v-model="dialog" title="创建授权安全任务" width="min(680px,92vw)"><el-form label-position="top"><div class="form-grid"><el-form-item label="任务名称"><el-input v-model="form.title"/></el-form-item><el-form-item label="任务类型"><el-select v-model="form.type"><el-option label="渗透测试" value="PENETRATION"/><el-option label="漏洞挖掘" value="BUG_BOUNTY"/><el-option label="安全审计" value="SECURITY_AUDIT"/><el-option label="红蓝对抗" value="RED_BLUE"/><el-option label="CTF 挑战" value="CTF"/></el-select></el-form-item></div><el-form-item label="任务描述"><el-input v-model="form.description" type="textarea" :rows="3"/></el-form-item><el-form-item label="授权目标资产"><el-input v-model="form.targetAssets" placeholder="明确域名、IP 或应用范围"/></el-form-item><div class="form-grid"><el-form-item label="开始日期"><el-input v-model="form.startDate" type="date"/></el-form-item><el-form-item label="结束日期"><el-input v-model="form.endDate" type="date"/></el-form-item><el-form-item label="奖励金额"><el-input-number v-model="form.rewardAmount" :min="0"/></el-form-item><el-form-item label="参与上限"><el-input-number v-model="form.memberLimit" :min="1" :max="1000"/></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="create">创建任务</el-button></template></el-dialog></div></template>
<style scoped>.role-notice{padding:16px 20px;display:flex;gap:15px;align-items:center;margin-bottom:12px}.role-notice svg{width:27px;color:#ffbf5b}.role-notice h3{font-size:13px;margin:0 0 5px}.role-notice p{font-size:10px;color:#75899d;margin:0}.ops-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:20px}.ops-stats>div{display:flex;align-items:center;gap:14px;padding:18px}.ops-stats svg{width:23px;color:#39d5ff}.ops-stats small,.ops-stats b{display:block}.ops-stats small{font-size:9px;color:#698095}.ops-stats b{font-size:23px}.ops-tabs{display:flex;border-bottom:1px solid #1d2c3d}.ops-tabs button{border:0;background:transparent;color:#788ba0;padding:12px 20px;border-bottom:2px solid transparent;cursor:pointer}.ops-tabs button.active{color:#6ee2fa;border-color:#39d5ff;background:#0d1b28}.table-wrap{border-top:0}.form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}@media(max-width:700px){.ops-stats{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.page-head{align-items:flex-start}}</style>
